<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import Settings from './components/Settings.vue'
import IndexPanel from './components/IndexPanel.vue'
import AnswerCard from './components/AnswerCard.vue'
import {api,exportJSON} from './view.js'
const state=ref(null),question=ref('Как Day 07 сохраняет историю диалога?'),result=ref(null),busy=ref(false),error=ref(''),run=ref(null),reviews=ref({})
const settings=ref({strategy:'structure',top_k_before:12,top_k_after:5,threshold:0.45})
let timer
async function refresh(){try{state.value=await api('/state');if(run.value && ['running','pending','queued'].includes(run.value.status)) run.value=await api(`/runs/${run.value.id}`)}catch(e){error.value=e.message}}
async function action(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function ask(){return action(async()=>{result.value=null;result.value=await api('/ask',{question:question.value,settings:settings.value})})}
function build(){return action(async()=>{await api('/build',{});await refresh()})}
function benchmark(){return action(async()=>{run.value=await api('/benchmark',{settings:settings.value});run.value=await api(`/runs/${run.value.id}`)})}
function cancel(){return action(async()=>{await api(`/runs/${run.value.id}/cancel`,{});await refresh()})}
onMounted(async()=>{await refresh();if(state.value?.active_run){const id=typeof state.value.active_run==='string'?state.value.active_run:state.value.active_run.id;run.value=await api(`/runs/${id}`)}timer=setInterval(refresh,1800)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><main class="layout"><header><span class="eyebrow">ДЕНЬ 24 / ПРОВЕРЯЕМ КАЖДОЕ УТВЕРЖДЕНИЕ</span><h1>Ответ, который можно проверить</h1><p>RAG с источниками, дословными цитатами и отказом при недостаточном контексте.</p><div class="steps"><span>1 · Поиск</span><span>2 · Порог</span><span>3 · Утверждения</span><span>4 · Точные цитаты</span><span>5 · Проверка смысла</span><span>6 · Ответ / «Не знаю»</span></div></header><p v-if="error" class="error panel" role="alert">{{ error }}</p><IndexPanel :state="state" :busy="busy" @build="build"/><section class="panel"><div class="row"><h2>Задайте вопрос по базе</h2><span class="badge">DeepSeek · генерация + verifier</span></div><Settings :settings="settings" :disabled="busy"/><textarea v-model="question" aria-label="Вопрос" :disabled="busy"/><div class="actions"><button @click="ask" :disabled="busy || !question.trim() || !state?.index?.ready">{{ busy?'Обрабатываем…':'Получить ответ с цитатами' }}</button></div><p v-if="!state?.index?.ready" class="tiny">Сначала соберите индекс документов.</p><details><summary>Контрольные вопросы и ожидания</summary><div v-for="q in state?.questions || []" :key="q.id" class="run-card"><button class="secondary" @click="question=q.question" :disabled="busy">{{ q.id }} · {{ q.question }}</button><p class="tiny">Ожидание: {{ typeof q.expected==='string'?q.expected:JSON.stringify(q.expected || q.expectation) }}</p></div></details></section><AnswerCard :result="result"/><section class="panel"><div class="row"><div><span class="eyebrow">10 КОНТРОЛЬНЫХ ВОПРОСОВ</span><h2>Источники, цитаты и соответствие смысла</h2></div><button @click="benchmark" :disabled="busy || !state?.index?.ready || ['running','pending','queued'].includes(run?.status)">Запустить живую проверку</button></div><p class="tiny">Каждый вопрос вызывает DeepSeek. Ожидания используются для просмотра результатов, а не подсказывают ответ модели.</p><template v-if="run"><div class="row"><p>{{ run.status }} · {{ run.current ?? run.results?.length ?? 0 }}/{{ run.total ?? 10 }}</p><div class="actions"><button class="danger" v-if="['running','pending','queued'].includes(run.status)" @click="cancel">Остановить после текущего запроса</button><button class="secondary" @click="exportJSON({run,manual_semantic_reviews:reviews},'day24-grounding.json')">Экспорт JSON</button></div></div><progress class="progress" :value="run.current ?? run.results?.length ?? 0" :max="run.total ?? 10"/><div v-if="run.summary" class="metrics"><span><b>{{ run.summary.answered }}/{{ run.summary.total }}</b>ответов</span><span><b>{{ run.summary.with_sources }}/{{ run.summary.source_denominator }}</b>ответов с источниками</span><span><b>{{ run.summary.with_quotes }}/{{ run.summary.source_denominator }}</b>ответов с цитатами</span><span><b>{{ run.summary.unknown }}</b>«не знаю»</span><span><b>{{ run.summary.errors }}</b>ошибок</span></div><p v-if="run.summary" class="tiny">Доля источников и цитат считается среди answered. Отказы и ошибки не входят в этот знаменатель.</p><pre v-if="run.summary">{{ JSON.stringify(run.summary,null,2) }}</pre><article v-for="(item,i) in run.results || []" :key="item.question_id || i" class="run-card"><h3>{{ item.question_id }} · {{ item.question }}</h3><p class="tiny">Ожидание: {{ typeof item.expected==='string'?item.expected:JSON.stringify(item.expected) }}</p><AnswerCard :result="item.result"/><label class="review">Ручная проверка смысла (только в браузере)<select v-model="reviews[item.question_id || i]"><option value="">Не проверено</option><option value="supported">Ответ согласуется с цитатами</option><option value="unsupported">Есть несоответствие</option><option value="uncertain">Недостаточно данных</option></select></label></article></template></section></main></template>
